std::string* shared_buffer = buffer;
std::string* prev_key = last_key;
const Slice& current_key = key;
const Slice& current_value = value;
int interval = restart_interval;
int* entry_counter = counter;
std::vector<uint32_t>* restart_points = restarts;

if (prev_key != nullptr && current_key.size() > 0) {
    size_t common_prefix = 0;
    while (common_prefix < prev_key->size() && common_prefix < current_key.size() &&
           (*prev_key)[common_prefix] == current_key[common_prefix]) {
        common_prefix++;
    }

    if (common_prefix != 0) {
        std::string shared_key = current_key.substr(common_prefix);
        current_key = Slice(shared_key);
    }
}

if (*entry_counter % interval == 0) {
    restart_points->push_back(shared_buffer->size());
}

std::string encoded_key = std::to_string(current_key.size()) + current_key.data();
std::string encoded_value = std::to_string(current_value.size()) + current_value.data();
shared_buffer->append(encoded_key);
shared_buffer->append(encoded_value);
*prev_key = current_key.ToString();
(*entry_counter)++;

